from flask import Flask, request
import sqlite3, subprocess

app = Flask(__name__)

@app.get("/orders")
def orders():
    name = request.args.get("customer", "")
    db = sqlite3.connect("shop.db")
    rows = db.execute(f"SELECT id, total FROM orders WHERE customer = '{name}'").fetchall()
    return {"orders": rows}

@app.get("/ping")
def ping():
    host = request.args.get("host", "127.0.0.1")
    out = subprocess.run(f"ping -c 1 {host}", shell=True, capture_output=True, text=True)
    return {"output": out.stdout}
